    enonce: "بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a + b + 11</span> حيث <span dir=\"ltr\" class=\"expr\">E = -(1 - a) + 2 - [-b - (1 - a)] - (-9 - a)</span>",
    correction: [{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">-(1 - a) = -1 + a</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [-b - (1 - a)] = b + 1 - a</span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">- (-9 - a) = 9 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -1 + a + 2 + b + 1 - a + 9 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = (a - a + a) + b + (-1 + 2 + 1 + 9)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 + 2 + 1 + 9 = 11</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a + b + 11</span>"}],
